import{_ as h,o as c,c as p,ah as g}from"./chunks/framework.C7CdSlIt.js";const d="/projects/MentorPi/en/2024-versions/assets/image2.BeLa6uol.png",m="/projects/MentorPi/en/2024-versions/assets/image3.Cl0lehr4.png",u="/projects/MentorPi/en/2024-versions/assets/image4.DhWQzOj9.png",y="/projects/MentorPi/en/2024-versions/assets/image2.BlscuZIk.png",b="/projects/MentorPi/en/2024-versions/assets/image3.vHZ18Zy5.png",f="/projects/MentorPi/en/2024-versions/assets/image4.BuLUtEuN.png",v="/projects/MentorPi/en/2024-versions/assets/image5.Cu54lNT2.jpeg",k="/projects/MentorPi/en/2024-versions/assets/image2.FwJU-WfO.png",A="/projects/MentorPi/en/2024-versions/assets/image3.DehcltIO.png",w="/projects/MentorPi/en/2024-versions/assets/image4.CwYVHRrx.png",C="/projects/MentorPi/en/2024-versions/assets/image5.D67lDVhD.png",F="/projects/MentorPi/en/2024-versions/assets/image6.BoXE-c7E.png",z="/projects/MentorPi/en/2024-versions/assets/image7.BMfPOL7N.png",E="/projects/MentorPi/en/2024-versions/assets/image8.C4mWuoOO.GIF",x="/projects/MentorPi/en/2024-versions/assets/image9.Br5X0Nef.png",q="/projects/MentorPi/en/2024-versions/assets/image10.6-0Pyvbw.png",I="/projects/MentorPi/en/2024-versions/assets/image11.YcKYq7HO.png",P="/projects/MentorPi/en/2024-versions/assets/image12.D0UojVh6.png",T="/projects/MentorPi/en/2024-versions/assets/image13.CJ81EfAM.png",B="/projects/MentorPi/en/2024-versions/assets/image14.DEPUn7TN.png",M="/projects/MentorPi/en/2024-versions/assets/image15.bmeRv0kc.png",S="/projects/MentorPi/en/2024-versions/assets/image16.BVq22dAH.png",N="/projects/MentorPi/en/2024-versions/assets/image17.DPCOrZlT.png",O="/projects/MentorPi/en/2024-versions/assets/image18.DSBPexRp.png",Z="/projects/MentorPi/en/2024-versions/assets/image19.uI6yi0x0.png",R="/projects/MentorPi/en/2024-versions/assets/image20.CubGI-gN.png",Y="/projects/MentorPi/en/2024-versions/assets/image21.DAGZRWsS.png",j="/projects/MentorPi/en/2024-versions/assets/image22.C3QtkC3K.png",G="/projects/MentorPi/en/2024-versions/assets/image23.CQt6DnTP.png",V="/projects/MentorPi/en/2024-versions/assets/image24.BYeEl2Wj.png",L="/projects/MentorPi/en/2024-versions/assets/image25.CNMwh1Bh.png",e="data:image/png;base64,",D="/projects/MentorPi/en/2024-versions/assets/image7.OCax69Xj.png",X="/projects/MentorPi/en/2024-versions/assets/image8.B83fldtl.png",Q="/projects/MentorPi/en/2024-versions/assets/image9.BZk9vu_G.png",J="/projects/MentorPi/en/2024-versions/assets/image10.Z4lf6fnj.png",U="/projects/MentorPi/en/2024-versions/assets/image11.a9aKQIJq.png",i="/projects/MentorPi/en/2024-versions/assets/image13.BwlH1cs1.png",a="/projects/MentorPi/en/2024-versions/assets/image14.BT3xyNZI.png",n="/projects/MentorPi/en/2024-versions/assets/image15.B0y5PgCO.png",s="data:image/png;base64,",o="/projects/MentorPi/en/2024-versions/assets/image17.DmZWVobK.png",r="/projects/MentorPi/en/2024-versions/assets/image18.BDt6Onpa.png",W="data:image/png;base64,",K="/projects/MentorPi/en/2024-versions/assets/image20.BNHjx68b.png",H="data:image/png;base64,",_="/projects/MentorPi/en/2024-versions/assets/image22.D9wxbxFS.png",$="/projects/MentorPi/en/2024-versions/assets/image23.Er4UsBhF.png",ee="/projects/MentorPi/en/2024-versions/assets/image24.BX_RDfPQ.png",te="data:image/png;base64,",ie="/projects/MentorPi/en/2024-versions/assets/image26.C7U4txA4.png",ae="/projects/MentorPi/en/2024-versions/assets/image27.Bg88YrN5.png",ne="data:image/png;base64,",se="/projects/MentorPi/en/2024-versions/assets/image31.B8jvgE8x.png",oe="/projects/MentorPi/en/2024-versions/assets/image32.ybrVMIdb.png",re="/projects/MentorPi/en/2024-versions/assets/image35.DGcEjQxu.png",le="/projects/MentorPi/en/2024-versions/assets/image36.Crsvt42K.png",he="/projects/MentorPi/en/2024-versions/assets/image40.CH2ErAmp.png",l="/projects/MentorPi/en/2024-versions/assets/image41.DsLFvYAG.png",ce="/projects/MentorPi/en/2024-versions/assets/image42.MBObO8nz.png",pe="/projects/MentorPi/en/2024-versions/assets/image43.DcDvd3s_.png",ge="/projects/MentorPi/en/2024-versions/assets/image45.rr9-au6D.png",de="/projects/MentorPi/en/2024-versions/assets/image46.B0YKaPpF.png",me="/projects/MentorPi/en/2024-versions/assets/image47.Bt_9KA2n.png",ue="/projects/MentorPi/en/2024-versions/assets/image48.BWRcn_oB.png",ye="data:image/png;base64,",be="/projects/MentorPi/en/2024-versions/assets/image51.CZvC3-s7.png",fe="/projects/MentorPi/en/2024-versions/assets/image52.BLTeoI7F.png",ve="/projects/MentorPi/en/2024-versions/assets/image54.DsiLSy61.png",ke="/projects/MentorPi/en/2024-versions/assets/image55.Il0hEjr_.png",Ae="/projects/MentorPi/en/2024-versions/assets/image56.1XA79uWp.png",we="/projects/MentorPi/en/2024-versions/assets/image57.BgICR_8r.png",Ce="/projects/MentorPi/en/2024-versions/assets/image58.D8ztNK_b.png",Be=JSON.parse('{"title":"10. Machine Learning","description":"","frontmatter":{},"headers":[],"relativePath":"docs/11.machine_learning.md","filePath":"docs/11.machine_learning.md"}'),Fe={name:"docs/11.machine_learning.md"};function ze(Ee,t,xe,qe,Ie,Pe){return c(),p("div",null,[...t[0]||(t[0]=[g('<h1 id="_10-machine-learning" tabindex="-1">10. Machine Learning <a class="header-anchor" href="#_10-machine-learning" aria-label="Permalink to &quot;10. Machine Learning&quot;">​</a></h1><h2 id="_10-1-machine-learning-introduction" tabindex="-1">10.1 Machine Learning Introduction <a class="header-anchor" href="#_10-1-machine-learning-introduction" aria-label="Permalink to &quot;10.1 Machine Learning Introduction&quot;">​</a></h2><h3 id="_10-1-1-preface" tabindex="-1">10.1.1 Preface <a class="header-anchor" href="#_10-1-1-preface" aria-label="Permalink to &quot;10.1.1 Preface&quot;">​</a></h3><p>Artificial Intelligence (AI) is a new interdisciplinary field of science and technology that studies and develops theories, methods, techniques, and application systems for simulating, extending, and expanding human intelligence.</p><p>AI includes machine learning, computer vision, natural language processing, and deep learning. Machine learning is a subfield of AI. Deep learning is a type of machine learning.</p><p>Since its inception, AI has matured in both theory and technology, and its application areas have continued to expand, gradually becoming an independent branch.</p><h3 id="_10-1-2-what-machine-learning-is" tabindex="-1">10.1.2 What &quot;Machine Learning&quot; is <a class="header-anchor" href="#_10-1-2-what-machine-learning-is" aria-label="Permalink to &quot;10.1.2 What &quot;Machine Learning&quot; is&quot;">​</a></h3><p>Machine Learning forms the cornerstone of artificial intelligence, serving as the fundamental approach to endow machines with intelligence. It spans multiple interdisciplinary fields such as probability theory, statistics, approximation theory, convex analysis, and algorithm complexity theory.</p><img loading="lazy" height="611" width="1257" class="common_img" src="'+d+'"><p>In essence, machine learning explores how computers can acquire new knowledge or skills by mimicking human learning behaviors and continuously enhancing their performance by reorganizing existing knowledge structures. Practically, it entails utilizing data to train models and leveraging these models for predictions.</p><p>For instance, consider AlphaGo, the pioneering artificial intelligence system that triumphed over human professional Go players and even world champions. AlphaGo operates on the principles of deep learning, wherein it discerns the intrinsic laws and representation layers within sample data to extract meaningful insights.</p><h3 id="_10-1-3-types-of-machine-learning" tabindex="-1">10.1.3 Types of Machine Learning <a class="header-anchor" href="#_10-1-3-types-of-machine-learning" aria-label="Permalink to &quot;10.1.3 Types of Machine Learning&quot;">​</a></h3><p>Machine learning can be broadly categorized into two types: supervised learning and unsupervised learning. The key distinction between these two types lies in whether the machine learning algorithm has prior knowledge of the classification and structure of the dataset.</p><ul><li><strong>Supervised Learning</strong></li></ul><p>Supervised learning involves providing a labeled dataset to the algorithm, where the correct answers are known. The machine learning algorithm uses this dataset to learn how to compute the correct answers. It is the most commonly used type of machine learning.</p><p>For instance, in image recognition, a large dataset of dog pictures can be provided, with each picture labeled as &quot;<strong>dog</strong>&quot;. This labeled dataset serves as the &quot;correct answer&quot;. By learning from this dataset, the machine can develop the ability to recognize dogs in new images.</p><img loading="lazy" height="436" width="582" class="common_img" src="'+m+'"><p>Model Selection: In supervised learning, selecting the right model to represent the data relationship is crucial. Common supervised learning models encompass linear regression, logistic regression, decision trees, support vector machines (SVM), and deep neural networks. The choice of model hinges on the data&#39;s characteristics and the problem&#39;s nature.</p><p>Feature Engineering: Feature engineering involves preprocessing and transforming raw data to extract valuable features. This encompasses tasks like data cleaning, handling missing values, normalization or standardization, feature selection, and feature transformation. Effective feature engineering can significantly enhance model performance and generalization capabilities.</p><p>Training and Optimization: Leveraging labeled training data, we can train the model to capture the data relationship. Training typically involves defining a loss function, selecting an appropriate optimization algorithm, and iteratively adjusting model parameters to minimize the loss function. Common optimization algorithms include gradient descent and stochastic gradient descent.</p><p>Model Evaluation: Upon completing training, evaluating the model&#39;s performance on new data is essential. Standard evaluation metrics include accuracy, precision, recall, F1 score, and ROC curve. Assessing a model&#39;s performance enables us to gauge its suitability for practical applications.</p><p>In summary, supervised learning entails utilizing labeled training data to train a model for predicting or classifying new unlabeled data. Key steps encompass selecting an appropriate model, conducting feature engineering, training and optimizing the model, and evaluating its performance. Together, these components constitute the foundational elements of supervised learning.</p><ul><li><strong>Unsupervised Learning</strong></li></ul><p>Unsupervised learning involves providing an unlabeled dataset to the algorithm, where the correct answers are unknown. In this type of machine learning, the machine must mine potential structural relationships within the dataset.</p><p>For instance, in image classification, a large dataset of cat and dog pictures can be provided without any labels. Through unsupervised learning, the machine can learn to divide the pictures into two categories: cat pictures and dog pictures.</p><img loading="lazy" height="526" width="1159" class="common_img" src="'+u+'"><h2 id="_10-2-machine-learning-library-introduction" tabindex="-1">10.2 Machine Learning Library Introduction <a class="header-anchor" href="#_10-2-machine-learning-library-introduction" aria-label="Permalink to &quot;10.2 Machine Learning Library Introduction&quot;">​</a></h2><h3 id="_10-2-1-common-type-of-machine-learning-framework" tabindex="-1">10.2.1 Common Type of Machine Learning Framework <a class="header-anchor" href="#_10-2-1-common-type-of-machine-learning-framework" aria-label="Permalink to &quot;10.2.1 Common Type of Machine Learning Framework&quot;">​</a></h3><p>There are a large variety of machine learning frameworks. Among them, PyTorch, Tensorflow, MXNet and paddlepaddle are common.</p><ul><li><strong>PyTorch</strong></li></ul><p>PyTorch is a powerful open-source machine learning framework, originally based on the BSD License Torch framework. It supports advanced multidimensional array operations and is widely used in the field of machine learning. PyTorch, built on top of Torch, offers even greater flexibility and functionality. One of its most distinguishing features is its support for dynamic computational graphs and its Python interface.</p><p>In contrast to TensorFlow&#39;s static computation graph, PyTorch&#39;s computation graph is dynamic. This allows for real-time modifications to the graph as computational needs change. Additionally, PyTorch enables developers to accelerate tensor calculations using GPUs, create dynamic computational graphs, and automatically calculate gradients. This makes PyTorch an ideal choice for machine learning tasks that require flexibility, speed, and powerful computing capabilities.</p><img loading="lazy" height="86" width="405" class="common_img" src="'+y+'"><ul><li><strong>TensorflowTensorflow</strong></li></ul><p>TensorFlow is a powerful open-source machine learning framework that allows users to quickly construct neural networks and train, evaluate, and save them. It provides an easy and efficient way to implement machine learning and deep learning concepts. TensorFlow combines computational algebra with optimization techniques to make the calculation of many mathematical expressions easier.</p><p>One of TensorFlow&#39;s key strengths is its ability to run on machines of varying sizes and types, including supercomputers, embedded systems, and everything in between. TensorFlow can also utilize both CPU and GPU computing resources, making it an extremely versatile platform. When it comes to industrial deployment, TensorFlow is often the most suitable machine learning framework due to its robustness and reliability. In other words, TensorFlow is an excellent choice for deploying machine learning applications in a production environment.</p><img loading="lazy" height="191" width="336" class="common_img" src="'+b+'"><ul><li><strong>PaddlePaddle</strong></li></ul><p>PaddlePaddle is a cutting-edge deep learning framework developed by Baidu, which integrates years of research and practical experience in deep learning. PaddlePaddle offers a comprehensive set of features, including training and inference frameworks, model libraries, end-to-end development kits, and a variety of useful tool components. It is the first open-source, industry-level deep learning platform to be developed in China, offering rich and powerful features to developers worldwide.</p><p>Deep learning has proven to be a powerful tool in many machine learning applications in recent years. From image recognition and speech recognition to natural language processing, robotics, online advertising, automatic medical diagnosis, and finance, deep learning has revolutionized the way we approach these fields. With PaddlePaddle, developers can harness the power of deep learning to create innovative and cutting-edge applications that meet the needs of users and businesses alike.</p><img loading="lazy" height="228" width="444" class="common_img" src="'+f+'"><ul><li><strong>MXNet</strong></li></ul><img loading="lazy" height="162" width="474" class="common_img" src="'+v+'"><p>MXNet is a top-tier deep learning framework that supports multiple programming languages, including Python, C++, Scala, R, and more. It features a dataflow graph similar to other leading frameworks like TensorFlow and Theano, as well as advanced features such as robust multi-GPU support and high-level model building blocks comparable to Lasagne and Blocks. MXNet can run on virtually any hardware, including mobile phones, making it a versatile choice for developers.</p><p>MXNet is specifically designed for efficiency and flexibility, with accelerated libraries that enable developers to leverage the full power of GPUs and cloud computing. It also supports distributed computing across dynamic cloud architectures via distributed parameter servers, achieving near-linear scaling with multiple GPUs/CPUs. Whether you&#39;re working on a small-scale project or a large-scale deep learning application, MXNet provides the tools and support you need to succeed.</p><h2 id="_10-3-yolov5-introduction" tabindex="-1">10.3 Yolov5 Introduction <a class="header-anchor" href="#_10-3-yolov5-introduction" aria-label="Permalink to &quot;10.3 Yolov5 Introduction&quot;">​</a></h2><h3 id="_10-3-1-yolo-series-model-introduction" tabindex="-1">10.3.1 Yolo Series Model Introduction <a class="header-anchor" href="#_10-3-1-yolo-series-model-introduction" aria-label="Permalink to &quot;10.3.1 Yolo Series Model Introduction&quot;">​</a></h3><ul><li><strong>YOLO Series</strong></li></ul><p>YOLO (You Only Look Once) is an one-stage regression algorithm based on deep learning.</p><p>R-CNN series algorithm dominates target detection domain before YOLOv1 is released. It has higher detection accuracy, but cannot achieve real-time detection due to its limited detection speed engendered by its two-stage network structure.</p><p>To tackle this problem, YOLO is released. Its core idea is to redefine target detection as a regression problem, use the entire image as network input, and directly return position and category of Bounding Box at output layer. Compared with traditional methods for target detection, it distinguishes itself in high detection speed and high average accuracy.</p><ul><li><strong>YOLOv5</strong></li></ul><p>YOLOv5 is an optimized version based on previous YOLO models, whose detection speed and accuracy is greatly improved.</p><p>In general, a target detection algorithm is divided into 4 modules, namely input end, reference network, Neck network and Head output end. The following analysis of improvements in YOLOv5 rests on these four modules.</p><p>(1) Input end: YOLOv5 employs Mosaic data enhancement method to increase model training speed and network accuracy at the stage of model training. Meanwhile, adaptive anchor box calculation and adaptive image scaling methods are proposed.</p><p>(2) Reference network: Focus structure and CPS structure are introduced in YOLOv5.</p><p>(3) Neck network: same as YOLOv4, Neck network of YOLOv5 adopts FPN+PAN structure, but they differ in implementation details.</p><p>(4) Head output layer: YOLOv5 inherits anchor box mechanism of output layer from YOLOv4. The main improvement is that loss function GIOU_Loss, and DIOU_nms for prediction box screening are adopted.</p><h3 id="_10-3-2-yolov5-model-structure" tabindex="-1">10.3.2 YOLOv5 Model Structure <a class="header-anchor" href="#_10-3-2-yolov5-model-structure" aria-label="Permalink to &quot;10.3.2 YOLOv5 Model Structure&quot;">​</a></h3><ul><li><strong>Component</strong></li></ul><p><strong>(1) Convolution layer: extract features of the image</strong></p><p>Convolution refers to the effect of a phenomenon, action or process that occurs repeatedly over time, impacting the current state of things. Convolution can be divided into two components: &quot;volume&quot; and &quot;accumulation&quot;.</p><p>&quot;<strong>Volume</strong>&quot; involves data flipping. &quot;<strong>accumulation</strong>&quot; refers to the accumulation of the influence of past data on current data. Flipping the data helps to establish the relationships between data points, providing a reference for calculating the influence of past data on the current data.</p><p>In YOLOv5, the data being processed is typically an image, which is two-dimensional in computer vision. Therefore, the convolution applied is also a two-dimensional convolution, with the aim of extracting features from the image. The convolution kernel is an unit area used for each calculation, typically in pixels. The kernel slides over the image, with the size of the kernel being manually set.</p><p>During convolution, the periphery of the image may remain unchanged or be expanded as needed, and the convolution result is then placed back into the corresponding position in the image. For instance, if an image has a resolution of 6×6, it may be first expanded to a 7×7 image, and then substituted into the convolution kernel for calculation. The resulting data is then refilled into a blank image with a resolution of 6×6.</p><img loading="lazy" height="358" width="1054" class="common_img" src="'+k+'"><img loading="lazy" height="739" width="703" class="common_img" src="'+A+'"><p><strong>(2) Pooling layer: enlarge the features of image</strong></p><p>The pooling layer is an essential part of a convolutional neural network and is commonly used for downsampling image features. It is typically used in combination with the convolutional layer. The purpose of the pooling layer is to reduce the spatial dimension of the feature map and extract the most important features.</p><p>There are different types of pooling techniques available, including global pooling, average pooling, maximum pooling, and more. Each technique has its unique effect on the features extracted from the image.</p><img loading="lazy" height="309" width="701" class="common_img" src="'+w+'"><p>Maximum pooling can extract the most distinctive features from an image, while discarding the remaining ones. For example, if we take an image with a resolution of 6×6 pixels, we can use a 2×2 filter to downsample the image and obtain a new image with reduced dimensions.</p><img loading="lazy" height="789" width="862" class="common_img" src="'+C+'"><p><strong>(3) Upsampling layer: restore the size of an image</strong></p><p>This process is sometimes referred to as &quot;<strong>anti-pooling</strong>&quot;. While upsampling restores the size of the image, it does not fully recover the features that were lost during pooling. Instead, it tries to interpolate the missing information based on the available information.</p><p>For example, let&#39;s consider an image with a resolution of 6×6 pixels. Before upsampling, use 3X3 filter to calculate the original image so as to get the new image.</p><img loading="lazy" height="750" width="787" class="common_img" src="'+F+'"><p><strong>(4) Batch normalization layer: organize data</strong></p><p>It aims to reduce the computational complexity of the model and to ensure that the data is better mapped to the activation function.</p><p>Batch normalization works by standardizing the data within each mini-batch, which reduces the loss of information during the calculation process. By retaining more features in each calculation, batch normalization can improve the sensitivity of the model to the data.</p><img loading="lazy" height="195" width="775" class="common_img" src="'+z+'"><p><strong>(5) RELU layer: activate function</strong></p><p>The activation function is a crucial component in the process of building a neural network, as it helps to increase the nonlinearity of the model. Without an activation function, each layer of the network would be equivalent to a matrix multiplication, and the output of each layer would be a linear function of the input from the layer above. This would result in a neural network that is unable to learn complex relationships between the input and output.</p><p>There are many different types of activation functions. Some of the most common activation functions include the ReLU, Tanh, and Sigmoid. For example, ReLU is a piecewise function that replaces all values less than zero with zero, while leaving positive values unchanged.</p><img loading="lazy" height="392" width="536" class="common_img" src="'+E+'"><p><strong>(6) ADD layer: add tensor</strong></p><p>In a typical neural network, the features can be divided into two categories: salient features and inconspicuous features.</p><img loading="lazy" height="316" width="836" class="common_img" src="'+x+'"><p><strong>(7) Concat layer: splice tensor</strong></p><p>It is used to splice together tensors of features, allowing for the combination of features that have been extracted in different ways. This can help to increase the richness and complexity of the feature set.</p><img loading="lazy" height="599" width="808" class="common_img" src="'+q+'"><ul><li><strong>Compound Element</strong></li></ul><p>When building a model, using only the layers mentioned above to construct functions can lead to lengthy, disorganized, and poorly structured code. By assembling basic elements into various units and calling them accordingly, the efficiency of writing the model can be effectively improved.</p><p><strong>(1) Convolutional unit:</strong></p><p>A convolutional unit consists of a convolutional layer, a batch normalization layer, and an activation function. The convolution is performed first, followed by batch normalization, and finally activated using an activation function.</p><img loading="lazy" height="293" width="821" class="common_img" src="'+I+'"><p><strong>(2) Focus module</strong></p><p>The Focus module for interleaved sampling and concatenation first divides the input image into multiple large regions and then concatenates the small images at the same position within each region to break down the input image into several smaller images. Finally, the images are preliminarily sampled using convolutional units.</p><p>As shown in the figure below, taking an image with a resolution of 6×6 as an example, if we set a large region as 2×2, then the image can be divided into 9 large regions, each containing 4 small images.</p><p>By concatenating the small images at position 1 in each large region, a 3×3 image can be obtained. The small images at other positions are similarly concatenated, and the original 6×6 image will be broken down into four 3×3 images.</p><img loading="lazy" height="418" width="1055" class="common_img" src="'+P+'"><p><strong>(3) Residual unit</strong></p><p>The function of the residual unit is to enable the model to learn small changes in the image. Its structure is relatively simple and is achieved by combining data from two paths.</p><p>The first path uses two convolutional units to sample the image, while the second path does not use convolutional units for sampling but directly uses the original image. Finally, the data from the first path is added to the second path.</p><img loading="lazy" height="287" width="963" class="common_img" src="'+T+'"><img loading="lazy" height="376" width="1060" class="common_img" src="'+B+'"><p><strong>(4) Composite Convolution Unit</strong></p><p>In YOLOv5, the composite convolution unit is characterized by the ability to customize the convolution unit according to requirements. The composite convolution unit is also realized by superimposing data obtained from two paths.</p><p>The first path only has one convolutional layer for sampling, while the second path has 2x+1 convolutional units and one convolutional layer for sampling. After sampling and splicing, the data is organized through batch normalization and then activated by an activation function. Finally, a convolutional layer is used for sampling.</p><img loading="lazy" height="750" width="522" class="common_img" src="'+M+'"><p><strong>(5) Compound Residual Convolutional Unit</strong></p><p>The compound residual convolutional unit replaces the 2x convolutional layers in the compound convolutional unit with x residual units. In YOLOv5, the feature of the compound residual unit is mainly that the residual units can be customized according to the needs.</p><img loading="lazy" height="750" width="522" class="common_img" src="'+S+'"><p><strong>(6) Composite Pooling Unit</strong></p><p>The output data of the convolutional unit is fed into three max pooling layers and an additional copy is kept without processing. Then, the data from the four paths are concatenated and input into a convolutional unit. Using the composite pooling unit to process the data can significantly enhance the features of the original data.&#39;</p><img loading="lazy" height="705" width="743" class="common_img" src="'+N+'"><ul><li><strong>Structure</strong></li></ul><p>Composed of three parts, YOLOv5 can output three sizes of data. Data of each size is processed in different way. The below picture is the output structure of YOLOv5.</p><img loading="lazy" height="1525" width="1215" class="common_img" src="'+O+'"><p>Below is the output structures of data of three sizes.</p><img loading="lazy" height="1414" width="928" class="common_img" src="'+Z+'"><img loading="lazy" height="1536" width="1081" class="common_img" src="'+R+'"><img loading="lazy" height="1710" width="1088" class="common_img" src="'+Y+'"><h3 id="_10-3-3-yolov5-running-procedure" tabindex="-1">10.3.3 YOLOv5 Running Procedure <a class="header-anchor" href="#_10-3-3-yolov5-running-procedure" aria-label="Permalink to &quot;10.3.3 YOLOv5 Running Procedure&quot;">​</a></h3><p>In this section, we provide an explanation of the model workflow using the anchor boxes, prediction boxes, and prior boxes employed in YOLOv5.</p><ul><li><strong>Prior Bounding Box</strong></li></ul><p>When an image is input into model, object detection area requires us to offer, while prior bounding box is that box used to mark the object detection area on image before detection.</p><img loading="lazy" height="588" width="1039" class="common_img" src="'+j+'"><ul><li><strong>Prediction Box</strong></li></ul><p>The prediction box is not required to set manually, which is the output result of the model. When the first batch of training data is input into model, the prediction box will be automatically generated with it. The position in which the object of same type appear more frequently are set as the center of the prediction box.</p><img loading="lazy" height="590" width="1039" class="common_img" src="'+G+'"><ul><li><strong>Anchor Box</strong></li></ul><p>After the prediction box is generated, deviation may occur in its size and position. At this time, the anchor box serves to calibrate the size and position of the prediction box.</p><p>The generation position of anchor box is determined by prediction box. In order to influence the position of the next generation of the prediction box, the anchor box is generated at the relative center of the existing prediction box.</p><img loading="lazy" height="586" width="1039" class="common_img" src="'+V+'"><ul><li><strong>Realization Process</strong></li></ul><p>After the data is calibrated, a prior bounding box appears on image. Then, the image data is input to the model, the model generates a prediction box based on the position of the prior bounding box. Having generated the prediction box, an anchor box will appear automatically. Lastly, the weights from this training are updated into model.</p><p>Each newly generated prediction will be influenced by the last generated anchor box. Repeating the operations above continuously, the deviation of the size and position of the prediction box will be gradually erased until it coincides with the priori box.</p><img loading="lazy" height="181" width="969" class="common_img" src="'+L+'"><h2 id="_10-4-yolov5-model-training" tabindex="-1">10.4 Yolov5 Model Training <a class="header-anchor" href="#_10-4-yolov5-model-training" aria-label="Permalink to &quot;10.4 Yolov5 Model Training&quot;">​</a></h2><p id="anchor_10_4_1"></p><h3 id="_10-4-1-image-collecting-labeling" tabindex="-1">10.4.1 Image Collecting &amp; Labeling <a class="header-anchor" href="#_10-4-1-image-collecting-labeling" aria-label="Permalink to &quot;10.4.1 Image Collecting &amp; Labeling&quot;">​</a></h3><p>Given that training the Yolov5 model necessitates a substantial volume of data, our initial step involves collecting and labeling the requisite data in preparation for subsequent model training.</p><p>To begin, you can assemble the images that require collection. As an illustration, let&#39;s consider the collection of traffic signs.</p><ul><li><strong>Image Collecting</strong></li></ul><p>Start the robot, and access the robot system desktop using VNC.</p><p>(1) Click-on <img loading="lazy" height="38" width="46" src="'+e+'"> to open the command-line terminal.</p><p>(2) Execute the command to terminate the app auto-start service.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">~</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/.stop_ros.sh</span></span></code></pre></div><p>(3) Run the command to initiate the depth camera service.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> launch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> peripherals</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> depth_camera.launch.py</span></span></code></pre></div><p>(4) Open a new command line terminal. Execute the command to create a directory for storing the data collection.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/my_data</span></span></code></pre></div><p>(5) Execute the command to open the image collecting tool.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/software/collect_picture</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.py</span></span></code></pre></div><img loading="lazy" height="644" width="703" class="common_img" src="'+D+'"><p>The &quot;<strong>save number</strong>&quot; displayed in the upper left corner represents the image ID, indicating the order in which images are saved. The term &quot;<strong>existing</strong>&quot; denotes the total number of images already saved.</p><p>(6) Click &quot;<strong>Select</strong>&quot;. Change the storage path to the created folder directory.</p><img loading="lazy" height="95" width="690" class="common_img" src="'+X+'"><p>(7) After selecting, click &quot;Choose&quot;.</p><img loading="lazy" height="581" width="873" class="common_img" src="'+Q+'"><p>(8) Position the target recognition content within the camera&#39;s field of view, then either click the &quot;<strong>Save</strong>&quot; button or press the space bar to capture the current image from the camera.</p><img loading="lazy" height="645" width="699" class="common_img" src="'+J+'"><p>(9) Click-on &quot;<strong>Save(space)</strong>&quot; or press space bar, then JPEGImages folder will be generated to save pictures.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>To enhance model reliability, capture target recognition content from various distances, rotation angles, and tilt angles.</p></section><p>(10) Once you have finished collecting the images, click-on &quot;<strong>Exit</strong>&quot; button to close the software.</p><img loading="lazy" height="104" width="696" class="common_img" src="'+U+'"><p>(11) In all the open command line terminals, click the &quot;<strong>Ctrl+C</strong>&quot; to exit.</p><ul><li><strong>Image Labeling</strong></li></ul><p>Labeling images is crucial for feature datasets as it enables the trained model to understand the categories of significant elements within the image. This understanding empowers the model to recognize these categories in new, previously unseen images.</p><p>Note: the input command should be case sensitive, and keywords can be complemented using Tab key.</p><p>(1) Open the command-line terminal, and execute the command to open the image labeling software.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./software/labelImg/labelImg.py</span></span></code></pre></div><p>The table below outlines the function of each icon:</p><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Icon</strong></th><th style="text-align:center;"><strong>Shortcut Key</strong></th><th style="text-align:center;"><strong>Function</strong></th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="60" width="144" src="'+i+'"></td><td style="text-align:center;">Ctrl+U</td><td style="text-align:center;">Select the directory where the picture is saved.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="60" width="144" src="'+a+'"></td><td style="text-align:center;">Ctrl+R</td><td style="text-align:center;">Select the directory where the calibration data is saved.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="55" width="144" src="'+n+'"></td><td style="text-align:center;">W</td><td style="text-align:center;">Create annotation box</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="55" width="144" src="'+s+'"></td><td style="text-align:center;">Ctrl+S</td><td style="text-align:center;">Save annotation</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="55" width="143" src="'+o+'"></td><td style="text-align:center;">A</td><td style="text-align:center;">Switch to the previous image</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="55" width="143" src="'+r+'"></td><td style="text-align:center;">D</td><td style="text-align:center;">Switch to the next image</td></tr></tbody></table><p>(2) Click <img loading="lazy" height="62" width="145" src="'+W+'"> to open the directory where the captured images are saved. In this section, it is as below:</p><img loading="lazy" height="88" width="953" class="common_img" src="'+K+'"><p>(3) After clicking <img loading="lazy" height="41" width="132" src="'+H+'">, the directory will be opened as shown in the figure.</p><img loading="lazy" height="673" width="1268" class="common_img" src="'+_+'"><p>(4) Click the <img loading="lazy" height="54" width="139" src="'+$+'"> on the interface. Select the corresponding storage folder for the calibration data directory. The path is the &quot;Annotations&quot; folder in the same path as the image capture.</p><img loading="lazy" height="191" width="963" class="common_img" src="'+ee+'"><p>(5) Click <img loading="lazy" height="47" width="135" src="'+te+'"> to return to the image annotation interface.</p><p>(6) Press the &quot;<strong>W</strong>&quot; key on the keyboard to initiate the creation of the label box.</p><p>(7) Position the mouse cursor appropriately, then press and hold the left mouse button while dragging it to encompass the entire target recognition content within the label box. Release the left mouse button to finalize the selection of the target recognition content.</p><img loading="lazy" height="336" width="533" class="common_img" src="'+ie+'"><p>(8) In the pop-up window, assign a category name to the target recognition content; for instance, &quot;<strong>left</strong>&quot;. Once you&#39;ve named it, either click the &quot;<strong>OK</strong>&quot; button or press the &quot;<strong>Enter</strong>&quot; key to save this category.</p><img loading="lazy" height="295" width="284" class="common_img" src="'+ae+'"><p>(9) Press the shortcut &quot;<strong>Ctrl+S</strong>&quot; to save the labeling data for the current picture.</p><p>(10) Press the &quot;<strong>d</strong>&quot; key to enter the annotation of the next image. Repeat steps 7 to 9 to complete the annotation of all images. Click <img loading="lazy" height="40" width="102" src="'+ne+'">in the upper right corner of the software to exit.</p><p>(11) Open a new command line. Run the command to view the annotation files.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my_data/Annotations</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span></span></code></pre></div><p id="anchor_10_4_2"></p><h3 id="_10-4-2-data-format-conversion" tabindex="-1">10.4.2 Data Format Conversion <a class="header-anchor" href="#_10-4-2-data-format-conversion" aria-label="Permalink to &quot;10.4.2 Data Format Conversion&quot;">​</a></h3><ul><li><strong>Getting Ready</strong></li></ul><p>Before proceeding with this section, ensure that image collection and annotation have been completed. For detailed operational steps, please refer to the &quot;<strong><a href="#anchor_10_4_1">10.4.1 Image Collecting and Labeling</a></strong>&quot;.</p><p>Prior to feeding the data into the YOLOv5 model for training, it is essential to assign categories to the images and convert the annotated data into the required format.</p><ul><li><strong>Format Conversion</strong></li></ul><p>Please operate the below steps after collecting and labeling the pictures.</p><p>Note: the input command should be case sensitive, and keywords can be complemented using Tab key.</p><p>(1) Open a new terminal, and execute the command to check the file.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vim</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/my_data/classes.names</span></span></code></pre></div><p>(2) Press the <strong>&quot;i</strong>&quot; key to enter editing mode and input the class name corresponding to the target recognition content. If multiple class names need to be added, each class name should be entered on a separate line. Ensure that the class name matches the one used during picture collection.</p><p>(3) After completing the editing, press the &quot;<strong>ESC</strong>&quot; key, type &quot;<strong>:wq</strong>&quot;, and press Enter to save and exit.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>The class name added here must match the one used in &#39;labelImg&#39;.</p></section><p>(4) Return to the command line terminal. Execute the command to convert the data format.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/software/xml2yolo.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --data</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/my_data</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --yaml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/my_data/data.yaml</span></span></code></pre></div><img loading="lazy" height="100" width="909" class="common_img" src="'+se+'"><p>Note: the path must be determined according to the actual location of the file.</p><p>In the command above, three parameters are involved:</p><p>(1) xml2yolo.py: This script converts the calibrated label format into a format compatible with YOLOv5 model conversion. Ensure the path corresponds correctly.</p><p>(2) my_data: This parameter specifies the folder you have labeled. Ensure the path corresponds correctly.</p><p>(3) data.yaml：This file represents the format conversion of the entire folder after the model segmentation. As indicated in the command, the saved directory is within the my_data folder.</p><p>(4) The image below illustrates the generated data.yaml file.</p><img loading="lazy" height="146" width="901" class="common_img" src="'+oe+'"><p>The points after the names represent the label type. &#39;nc&#39; denotes the number of label types, &#39;train&#39; signifies the training set (used for data training in deep learning), and the subsequent parameters denote the paths. &#39;val&#39; represents the validation set, which is used to verify results during the data training process. Ensure that paths are filled in or replaced according to the actual locations.</p><p>In subsequent training processes, if you need to enhance training speed by moving the dataset from the vehicle to a local PC or cloud server, ensure to replace the paths corresponding to the current &#39;train&#39; and &#39;val&#39; datasets.</p><p>Finally, an XML file will be generated under the &quot;<strong>/my_data</strong>&quot; folder to locate the segmented dataset. You can also change the saved path by modifying the last parameter in the 4) command &quot;<strong>/my_data/data.yaml</strong>&quot;. Remember the path of this file as it will be used for model training later.</p><h3 id="_10-4-3-model-training" tabindex="-1">10.4.3 Model Training <a class="header-anchor" href="#_10-4-3-model-training" aria-label="Permalink to &quot;10.4.3 Model Training&quot;">​</a></h3><p>Note: the input command should be case sensitive, and the keywords can be complemented using Tab key.</p><ul><li><strong>Getting Ready</strong></li></ul><p>After converting the model format, the next step is to proceed with model training. However, before training, ensure that the dataset has been prepared and converted into the required format. For detailed instructions, please refer to &quot;<strong><a href="#anchor_10_4_2">10.4.2 Data Format Conversion</a></strong>&quot;.</p><ul><li><strong>Model Training</strong></li></ul><p>(1) Start the robot, and access the robot system desktop using VNC.</p><p>(2) Click-on <img loading="lazy" height="38" width="46" src="'+e+'"> to open the command-line terminal.</p><p>(3) Execute the command to navigate to the designated directory.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/third_party_ros2/yolov5/</span></span></code></pre></div><p>(4) Run the command to train model.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> train.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --img</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 640</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --batch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 64</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --epochs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 300</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --data</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/my_data/data.yaml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --weights</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yolov5n.pt</span></span></code></pre></div><p>In the command, &quot;<strong>--img</strong>&quot; specifies the image size; &quot;<strong>--batch</strong>&quot; determines the number of single input images per batch; &quot;<strong>--epochs</strong>&quot; indicates the number of training iterations; &quot;<strong>--data</strong>&quot; denotes the path to the dataset; &quot;<strong>--weights</strong>&quot; represents the location of the initial training file.</p><p>You can adjust these parameters according to your specific requirements. For instance, to enhance model reliability, one can increase the number of training iterations, though this will also extend the training duration.</p><p>If the content shown in the picture below appears, it indicates that the training is in progress.</p><img loading="lazy" height="444" width="1267" class="common_img" src="'+re+'"><p>Upon completion of the model training, the path to the generated file will be displayed in the terminal and recorded. This path will be utilized in the subsequent course.</p><img loading="lazy" height="119" width="1253" class="common_img" src="'+le+'"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>The path to the generated file may vary and can be located in the corresponding folder within runs/train.</p></section><h3 id="_10-4-4-traffic-sign-model-training" tabindex="-1">10.4.4 Traffic Sign Model Training <a class="header-anchor" href="#_10-4-4-traffic-sign-model-training" aria-label="Permalink to &quot;10.4.4 Traffic Sign Model Training&quot;">​</a></h3><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>Please use the actual product names and reference paths as they appear in the document.</p></section><p>For large datasets, it is not recommended to use the controller on the robot for training due to its slower training speed caused by I/O port speed and memory limitations. It is advisable to use a computer equipped with a dedicated graphics card for faster training. The training process remains the same, and you only need to configure the relevant program running environment.</p><p>If the performance of traffic sign recognition in the driverless game is poor and you need to train your own model, you can refer to this section for training the traffic sign model.</p><p>The screenshots in the following instructions may display different robot host names (though the environment configurations of different robots are roughly the same). Please input them according to the document content; however, it will not affect the execution.</p><ul><li><strong>Getting Ready</strong></li></ul><p>(1) Prepare a laptop, or a PC with wireless network card and mouse.</p><p>(2) Access the robot system desktop using VNC.</p><ul><li><strong>Training Instructions</strong></li></ul><p>(1) Image Collecting</p><p>① Start the robot, and access the robot system desktop using VNC.</p><p>② Click-on <img loading="lazy" height="38" width="46" src="'+e+'"> to open the command-line terminal.</p><p>③ Execute the command to terminate the app service.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">~</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/.stop_ros.sh</span></span></code></pre></div><p>④ Run the command to initiate the camera service.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> launch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> peripherals</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> depth_camera.launch.py</span></span></code></pre></div><p>⑤ Open a new terminal window. Navigate to the directory where the collection tool is stored, then enter the command to launch the image collection tool.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> software/collect_picture</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.py</span></span></code></pre></div><img loading="lazy" height="627" width="665" class="common_img" src="'+he+'"><p>&quot;<strong>save number</strong>&quot; represents the picture ID, indicating which picture has been saved. &quot;<strong>existing</strong>&quot; denotes the total number of saved images.</p><p>⑥ Change the storage path to &quot;/home/ubuntu/my_data&quot;.</p><img loading="lazy" height="111" width="693" class="common_img" src="'+l+'"><p>⑦ Position the target recognition content within the camera&#39;s field of view, then click the &quot;<strong>Save (space)</strong>&quot; button or press the space bar to capture and save the current camera image. Upon saving, both the &quot;<strong>save number</strong>&quot; and &quot;<strong>existing</strong>&quot; counts will increment by 1. These two parameters allow for monitoring of the saved picture names displayed on the current camera screen and the total number of pictures stored in the folder.</p><img loading="lazy" height="650" width="700" class="common_img" src="'+ce+'"><p>Upon selecting the &quot;<strong>Save (space)</strong>&quot; option, a JPEGImages folder will automatically be created within the directory &quot;<strong>/home/ubuntu/my_data</strong>&quot; to store the images.</p><img loading="lazy" height="111" width="693" class="common_img" src="'+l+'"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><ul><li><p>For enhanced model reliability, capture target recognition content from various distances, rotation angles, and tilt angles.</p></li><li><p>To guarantee recognition stability, it&#39;s advisable to increase the number of training images. It is recommended that each image category comprises at least 200 images for effective model training.</p></li></ul></section><p>⑧ After image collecting, click-on &quot;<strong>Exit</strong>&quot; to close this software.</p><img loading="lazy" height="627" width="665" class="common_img" src="'+pe+'"><p>(2) Image Labeling</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>The input command should be case sensitive, and keywords can be complemented using Tab key.</p></section><p>① Start the robot, and access the robot system desktop using VNC.</p><p>② Click-on <img loading="lazy" height="38" width="46" src="'+e+'"> to open the command-line terminal.</p><p>③ Execute the command to terminate the app service.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">~</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/.stop_ros.sh</span></span></code></pre></div><p>④ Create a new terminal to execute the command.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> software/labelImg/labelImg.py</span></span></code></pre></div><p>⑤ Upon launching the image annotation tool, the table below outlines the key functions</p><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Icon</strong></th><th style="text-align:center;"><strong>Shortcut Key</strong></th><th style="text-align:center;"><strong>Function</strong></th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="60" width="144" src="'+i+'"></td><td style="text-align:center;">Ctrl+U</td><td style="text-align:center;">Select the directory where the picture is saved.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="60" width="144" src="'+a+'"></td><td style="text-align:center;">Ctrl+R</td><td style="text-align:center;">Select the directory where the calibration data is saved.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="55" width="144" src="'+n+'"></td><td style="text-align:center;">W</td><td style="text-align:center;">Create annotation box</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="55" width="144" src="'+s+'"></td><td style="text-align:center;">Ctrl+S</td><td style="text-align:center;">Save annotation</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="55" width="143" src="'+o+'"></td><td style="text-align:center;">A</td><td style="text-align:center;">Switch to the previous image</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="55" width="143" src="'+r+'"></td><td style="text-align:center;">D</td><td style="text-align:center;">Switch to the next image</td></tr></tbody></table><p>⑥ Press &quot;<strong>Ctrl+U</strong>&quot; to designate the image storage directory as &quot;/home/ubuntu/my_data/JPEGImages/&quot;, then click the &quot;<strong>Open</strong>&quot; button.</p><img loading="lazy" height="372" width="805" class="common_img" src="'+ge+'"><p>⑦ Press &quot;<strong>Ctrl+R</strong>&quot; to specify the calibration data storage directory as &quot;/home/ubuntu/my_data/Annotations&quot;. The &quot;<strong>Annotations</strong>&quot; folder is automatically created during image collection. Click the &quot;<strong>Open</strong>&quot; button.</p><img loading="lazy" height="308" width="804" class="common_img" src="'+de+'"><p>⑧ Press the &quot;<strong>W</strong>&quot; key to initiate label box creation.</p><p>Position the mouse cursor appropriately, then press and hold the left mouse button while dragging to encompass the entire target recognition content within the label box. Release the left mouse button to finalize the selection of the target recognition content.</p><img loading="lazy" height="722" width="963" class="common_img" src="'+me+'"><p>⑨ In the pop-up window, assign a name to the category of the target recognition content, such as &quot;<strong>right</strong>&quot;. Once the naming is complete, either click the &quot;<strong>OK</strong>&quot; button or press the &quot;<strong>Enter</strong>&quot; key to save this category.</p><img loading="lazy" height="276" width="278" class="common_img" src="'+ue+'"><p>⑩ Use short-cut &#39;<strong>Ctrl+S</strong>&#39; to save the labeled data of the current pictures.</p><p>⑪ Label the remaining pictures in the same manner as step 9).</p><p>⑫ Click <img loading="lazy" height="52" width="51" src="'+ye+'"> in the system status bar to open the file manager. Navigate to the directory &quot;<strong>/home/ubuntu/my_data/Annotations/</strong>&quot; to view the picture annotation file.</p><p>(3) Generate Related Files</p><p>① Click-on <img loading="lazy" height="38" width="46" src="'+e+'"> to open the command-line terminal.</p><p>② Execute the command to view the file.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vim</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/my_data/classes.names</span></span></code></pre></div><p>③ Press the &quot;<strong>i</strong>&quot; key to enter the editing mode and input the class name of the target recognition content. If multiple class names are required, enter them one per line.</p><img loading="lazy" height="429" width="728" class="common_img" src="'+be+'"><p>Note: The class name entered here must match the naming convention used in the image annotation software &quot;<strong>labelImg</strong>&quot; when applicable.</p><p>④ Having finish input, press &#39;<strong>Esc</strong>&#39; key, and input &#39;<strong>:wq</strong>&#39; to save the change and close the file.</p><img loading="lazy" height="428" width="733" class="common_img" src="'+fe+'"><p>⑤ Execute the command to convert the data format.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> software/xml2yolo.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --data</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/my_date</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --yaml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/my_data/data.yaml</span></span></code></pre></div><p>The xml2yolo.py script converts annotated files into XML format, organizes the dataset into training and validation sets.</p><p>If you encounter the following prompt, the conversion is successful.</p><img loading="lazy" height="116" width="1265" class="common_img" src="'+ve+'"><p>The output paths may vary on different robots based on their actual storage locations. However, the generated data.yaml file corresponds to the calibrated dataset.</p><p>(4) Model Training</p><p>① Click-on <img loading="lazy" height="38" width="46" src="'+e+'"> to open the command-line terminal.</p><p>② Execute the command to navigate to the designated directory.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/third_party_ros2/yolov5/</span></span></code></pre></div><p>③ Run the command to train the model.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> train.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --img</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 640</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --batch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --epochs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 300</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --data</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/my_data/data.yaml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --weights</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yolov5n.pt</span></span></code></pre></div><p>In the command, &quot;<strong>--img</strong>&quot; specifies the image size, &quot;<strong>--batch</strong>&quot; determines the number of images processed in each iteration, and &quot;<strong>--epochs</strong>&quot; denotes the number of training iterations, which impacts the quality of the final model. For quick testing, we&#39;ve set the number of training iterations to 8, but for optimal results, this value should be adjusted based on your specific requirements and the capabilities of your computer system.</p><p>Furthermore, &quot;<strong>--data</strong>&quot; indicates the path to the calibrated dataset, while &quot;<strong>--weights</strong>&quot; refers to the path of the pretrained model. It&#39;s crucial to remember whether you&#39;re using &quot;<strong>yolov5n.pt</strong>&quot; or &quot;<strong>yolov5s.pt</strong>&quot; as your pretrained model.</p><p>You can customize these parameters according to your specific needs. If model reliability needs to be improved, consider increasing the number of training iterations, keeping in mind that this will also extend the training time.</p><p>④ When the option displayed in the figure below appears, input &quot;<strong>3</strong>&quot; and press Enter.</p><img loading="lazy" height="200" width="1125" class="common_img" src="'+ke+'"><p>If the content displayed in the image below appears, it indicates that the training is ongoing.</p><img loading="lazy" height="260" width="833" class="common_img" src="'+Ae+'"><p>After the model has been trained successfully, the terminal will print the path containing the file, and you need to record the path which will be required for &quot;<strong>Generate TensorRt Model Engine</strong>&quot;.</p><img loading="lazy" height="45" width="620" class="common_img" src="'+we+'"><img loading="lazy" height="25" width="620" class="common_img" src="'+Ce+'"><p>Notice: If multiple trainings are conducted, the naming of the &quot;<strong>exp5</strong>&quot; folder mentioned here will vary. For instance, it might be changed to &quot;<strong>exp2</strong>&quot;, &quot;<strong>exp3</strong>&quot;, and so on. The following steps will be associated with the folder naming used in this step.</p><ul><li>Model Usage</li></ul><p>(1) Enter the command. Press &quot;<strong>Enter</strong>&quot; to disable the app service.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">~</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/.stop_ros.sh</span></span></code></pre></div><p>(2) Execute the command to navigate to the file folder of training result.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> third_party_ros2/yolov5/runs/train/exp5/weights</span></span></code></pre></div><p>(3) Copy the trained model to the ros2 function pack of the yolov5.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> best.pt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/ros2_ws/src/yolov5_ros2/config</span></span></code></pre></div><p>(4) Run the command to open the depth camera node.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> launch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> peripherals</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> depth_camera.launch.py</span></span></code></pre></div><p>(5) Open a new command line terminal. Execute the command to open the yolov5 node. Assign the current model as the copied model &quot;<strong>best</strong>&quot;.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> launch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yolov5_ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yolov5_ros2.launch.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> model:=&quot;best&quot;</span></span></code></pre></div>',329)])])}const Me=h(Fe,[["render",ze]]);export{Be as __pageData,Me as default};
